    reg_intro_titel: 'Konto & Stammbaum – kurz erklärt',
    reg_intro_text: 'Mit diesem Formular erstellst du dein Konto. Gib die Daten deines Familienstammbaums ein (Name, Land, Ort, Gemeinde). Ein „Stammbaum" ist dabei deine Familienlinie – in der Regel der Familien-Nachname. Existiert dieser Stammbaum schon, kannst du ihm beitreten und um Zugang bitten (ein Admin bestätigt). Gibt es ihn noch nicht, wird automatisch ein neuer, eigener Stammbaum für dich angelegt – du wirst dessen Eigentümer und kannst danach Personen hinzufügen.',
