    reg_intro_titel: 'Račun i stablo – ukratko',
    reg_intro_text: 'Ovim obrascem izrađuješ svoj račun. Unesi podatke svojeg obiteljskog stabla (naziv, država, mjesto, općina). „Stablo" je tvoja obiteljska linija – u pravilu obiteljsko prezime. Ako ovo stablo već postoji, možeš mu se pridružiti i zatražiti pristup (administrator potvrđuje). Ako još ne postoji, automatski se izrađuje novo, vlastito stablo za tebe – postaješ njegov vlasnik i možeš zatim dodavati osobe.',
